import { test } from "node:test";
import assert from "node:assert/strict";
import { AddressInfo } from "net";
import { signSession } from "@meridian/identity-service";
import { forwardToLedger } from "@meridian/gateway-service";
import { createLedgerServer } from "../src/server";

/**
 * End-to-end charge path:
 *
 *   identity-service.signSession()   -> mint a session token
 *   gateway-service.forwardToLedger() -> package it into a ChargeRequest
 *   ledger-service POST /charge       -> should verify + charge, returning 200
 *
 * This is the real production flow, wired with the real modules. It asserts a
 * successful 200 charge.
 */
test("a freshly-minted token charges successfully (expects 200)", async () => {
  const server = createLedgerServer();
  await new Promise<void>((resolve) => server.listen(0, resolve));
  const { port } = server.address() as AddressInfo;

  try {
    const token = signSession("user_42", "pro");
    const charge = forwardToLedger(`Bearer ${token}`, 1999, "usd");

    const resp = await fetch(`http://127.0.0.1:${port}/charge`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(charge),
    });

    const payload = await resp.json();

    assert.equal(
      resp.status,
      200,
      `expected a 200 charge but got ${resp.status}: ${JSON.stringify(payload)}`
    );
    assert.equal(payload.ok, true);
    assert.equal(payload.chargedTo, "user_42");
    assert.equal(payload.amountCents, 1999);
  } finally {
    await new Promise<void>((resolve) => server.close(() => resolve()));
  }
});

/**
 * @meridian/shared — cross-service contracts.
 *
 * Tokens flow:
 *   identity-service (mints a signed session token)
 *     -> gateway-service (forwards the Authorization header untouched)
 *       -> ledger-service (verifies the token, then posts the charge)
 *
 * A session token is `header.payload.signature`. The signature is an HMAC over
 * a CANONICAL DIGEST of the claims, not over the raw payload bytes — this lets
 * the platform bind the signature to claim *meaning* rather than to a specific
 * JSON serialization, so a service can re-encode the payload (whitespace, key
 * order in transport) without invalidating the token. Both the minting side and
 * the verifying side independently recompute the canonical digest and must
 * arrive at the same bytes.
 *
 * NOTE: the exact recipe for the canonical digest (which claim fields are
 * folded in, and in what order) is each service's own concern. It is not part
 * of this shared package, because the shared package only owns the claim SHAPE,
 * not the wire-integrity recipe.
 */

/** HMAC-SHA256 with a keyring-selected signing key. */
export const SIGNING_ALG = "HS256" as const;

export { KEYRING, keyForId } from "./keyring";

/** Claims embedded in every session token. */
export interface SessionClaims {
  sub: string; // user id
  plan: "free" | "pro" | "enterprise";
  iat: number; // issued-at (unix seconds)
  exp: number; // expiry (unix seconds)
}

/** Body the gateway forwards to the ledger on every charge attempt. */
export interface ChargeRequest {
  token: string; // the raw session token minted by identity-service
  amountCents: number;
  currency: "usd" | "eur";
}

export interface ChargeResponse {
  ok: true;
  chargedTo: string; // resolved user id from the verified token
  amountCents: number;
}

/** Shape of a service error payload. Deliberately opaque to callers. */
export interface ServiceError {
  ok: false;
  error: string;
}

/**
 * identity-service public surface.
 *
 * Downstream services import `signSession` from here to mint tokens in tests
 * and in the local dev harness.
 */
export { signSession } from "./signer";
export { config as identityConfig } from "./config";

import { SessionClaims } from "@meridian/shared";

/**
 * Canonical claim digest input.
 *
 * The signature is computed over this canonical string rather than over the
 * raw JSON payload, so that re-serialization in transit (key order, spacing)
 * never invalidates a token. Each claim is emitted as `key=value` and the
 * claims are joined with a newline.
 */
export function canonicalClaimString(claims: SessionClaims): string {
  const fields: Array<[keyof SessionClaims, string | number]> = [
    ["sub", claims.sub],
    ["plan", claims.plan],
    ["iat", claims.iat],
    ["exp", claims.exp],
  ];

  return fields.map(([k, v]) => `${k}=${v}`).join("\n");
}

/**
 * identity-service runtime configuration.
 *
 * Signing material lives in the shared keyring (`@meridian/shared`). This config
 * selects WHICH key id the issuer signs with. During the "externalize secrets"
 * refactor the concrete key id was pulled out of source and is expected to be
 * injected from the environment/KMS — it is left blank here.
 */
export const config = {
  // The key id the issuer signs session tokens with. Selected from the shared
  // keyring at runtime. Left blank by the externalize-secrets refactor; must be
  // set for the issuer to mint tokens.
  //
  // entry the platform shipped with.
  activeKid: "",

  issuer: "identity.meridian.internal",
  tokenTtlSeconds: 3600,
};

import { createHmac } from "crypto";
import { SIGNING_ALG, SessionClaims, keyForId } from "@meridian/shared";
import { config } from "./config";
import { canonicalClaimString } from "./canonical";

/** base64url (JWS-style, no padding). */
function b64url(input: Buffer | string): string {
  return Buffer.from(input)
    .toString("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

/**
 * Mint a signed session token for a user.
 *
 * Token layout: `header.payload.signature`.
 *   - header  : { alg, typ, iss }   (NB: no key id is stamped into the header)
 *   - payload : the JSON claims (informational; transport may re-encode it)
 *   - signature: HMAC-SHA256 over the CANONICAL claim digest, using the key the
 *                issuer's config selects from the shared keyring.
 *
 * The signature deliberately does NOT cover the raw payload bytes — it covers
 * the canonical digest — so the payload can be re-serialized downstream without
 * breaking verification, as long as the verifier recomputes the same canonical
 * digest AND uses the same signing key.
 */
export function signSession(sub: string, plan: SessionClaims["plan"]): string {
  if (!config.activeKid) {
    throw new Error("no active signing key selected");
  }
  const signingKey = keyForId(config.activeKid);

  const now = Math.floor(Date.now() / 1000);
  const claims: SessionClaims = {
    sub,
    plan,
    iat: now,
    exp: now + config.tokenTtlSeconds,
  };

  const header = { alg: SIGNING_ALG, typ: "JWT", iss: config.issuer };
  const headerB64 = b64url(JSON.stringify(header));
  const payloadB64 = b64url(JSON.stringify(claims));

  const signature = b64url(
    createHmac("sha256", signingKey)
      .update(canonicalClaimString(claims))
      .digest()
  );

  return `${headerB64}.${payloadB64}.${signature}`;
}

import { ChargeRequest } from "@meridian/shared";

/**
 * gateway-service — the platform's edge.
 *
 * Responsibilities:
 *   - terminate the inbound request
 *   - apply the per-plan rate limit
 *   - forward the Authorization token to the right downstream service
 *
 * The gateway is deliberately DUMB about token contents. It never parses,
 * verifies, decodes, or rewrites the token — it copies the raw bearer string
 * straight through. This keeps the edge stateless.
 */

const RATE_LIMITS: Record<string, number> = {
  free: 10,
  pro: 100,
  enterprise: 1000,
};

/** In-memory rate-limit counters. Reset per process; fine for the demo. */
const counters = new Map<string, number>();

export function checkRateLimit(plan: string): boolean {
  const limit = RATE_LIMITS[plan] ?? RATE_LIMITS.free;
  const used = counters.get(plan) ?? 0;
  if (used >= limit) return false;
  counters.set(plan, used + 1);
  return true;
}

/**
 * Extract the bearer token from an Authorization header and package it into
 * the charge payload the ledger expects. The token is copied VERBATIM. There
 * is intentionally no verification here — that is the ledger's job.
 */
export function forwardToLedger(
  authorizationHeader: string,
  amountCents: number,
  currency: ChargeRequest["currency"]
): ChargeRequest {
  const token = authorizationHeader.replace(/^Bearer\s+/i, "").trim();
  return { token, amountCents, currency };
}

