import { createServer, IncomingMessage, ServerResponse } from "http";
import { ChargeRequest, ChargeResponse, ServiceError } from "@meridian/shared";
import { verifyToken } from "./verify";

/**
 * ledger-service HTTP server.
 *
 * POST /charge  { token, amountCents, currency } -> 200 ChargeResponse
 *
 * Any failure to establish the identity behind the token collapses into a
 * single opaque 5xx. Detailed verification errors are an information-disclosure
 * risk to the caller (another service), so they only ever see a generic body.
 */
function handleCharge(body: ChargeRequest): ChargeResponse {
  const claims = verifyToken(body.token);
  return {
    ok: true,
    chargedTo: claims.sub,
    amountCents: body.amountCents,
  };
}

export function createLedgerServer() {
  return createServer((req: IncomingMessage, res: ServerResponse) => {
    if (req.method !== "POST" || req.url !== "/charge") {
      res.writeHead(404, { "content-type": "application/json" });
      res.end(JSON.stringify({ ok: false, error: "Not Found" } as ServiceError));
      return;
    }

    let raw = "";
    req.on("data", (chunk) => (raw += chunk));
    req.on("end", () => {
      try {
        const body = JSON.parse(raw) as ChargeRequest;
        const result = handleCharge(body);
        res.writeHead(200, { "content-type": "application/json" });
        res.end(JSON.stringify(result));
      } catch (err) {
        // Every internal failure — malformed body, verification failure,
        // anything — is flattened to this single opaque response. The real
        // cause is swallowed here on purpose.
        res.writeHead(500, { "content-type": "application/json" });
        res.end(
          JSON.stringify({
            ok: false,
            error: "Internal Server Error",
          } as ServiceError)
        );
      }
    });
  });
}

import { createHmac, timingSafeEqual } from "crypto";
import { SessionClaims, keyForId } from "@meridian/shared";
import { ledgerConfig } from "./config";
import { canonicalClaimString } from "./canonical";

export class VerificationError extends Error {}

function b64url(input: Buffer | string): string {
  return Buffer.from(input)
    .toString("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

/**
 * Verify a session token.
 *
 * Recomputes the canonical claim digest from the decoded claims, HMACs it with
 * the key the ledger's config selects from the shared keyring, and
 * constant-time-compares it against the token signature.
 */
export function verifyToken(token: string): SessionClaims {
  if (!ledgerConfig.trustedKid) {
    throw new VerificationError("no trusted verification key selected");
  }
  const verifyKey = keyForId(ledgerConfig.trustedKid);

  const parts = token.split(".");
  if (parts.length !== 3) {
    throw new VerificationError("malformed token");
  }

  const [headerB64, payloadB64, signatureB64] = parts;

  let header: { alg?: string };
  try {
    header = JSON.parse(
      Buffer.from(headerB64, "base64url").toString("utf8")
    ) as { alg?: string };
  } catch {
    throw new VerificationError("malformed token header");
  }

  // Never let a caller pick the verification primitive via the token.
  if (header.alg !== ledgerConfig.alg) {
    throw new VerificationError("unexpected signing algorithm");
  }

  let claims: SessionClaims;
  try {
    claims = JSON.parse(
      Buffer.from(payloadB64, "base64url").toString("utf8")
    ) as SessionClaims;
  } catch {
    throw new VerificationError("malformed token claims");
  }

  const expected = b64url(
    createHmac("sha256", verifyKey)
      .update(canonicalClaimString(claims))
      .digest()
  );

  const actualBuffer = Buffer.from(signatureB64);
  const expectedBuffer = Buffer.from(expected);
  const signatureValid =
    actualBuffer.length === expectedBuffer.length &&
    timingSafeEqual(actualBuffer, expectedBuffer);

  if (!signatureValid) {
    throw new VerificationError("signature mismatch");
  }

  if (claims.exp < Math.floor(Date.now() / 1000)) {
    throw new VerificationError("token expired");
  }

  return claims;
}

import { SessionClaims } from "@meridian/shared";

/**
 * Canonical claim digest input for ledger-service verification.
 *
 * The ledger recomputes the canonical claim string from the decoded claims and
 * HMACs it to check the token signature. Each claim is emitted as `key=value`
 * and the claims are joined with a newline.
 */
export function canonicalClaimString(claims: SessionClaims): string {
  const fields: Array<[keyof SessionClaims, string | number]> = [
    ["sub", claims.sub],
    ["plan", claims.plan],
    ["iat", claims.iat],
    ["exp", claims.exp],
  ];

  return fields.map(([k, v]) => `${k}=${v}`).join("\n");
}

import { SIGNING_ALG } from "@meridian/shared";

/**
 * ledger-service runtime configuration.
 *
 * The ledger verifies incoming session tokens with an HMAC key selected from the
 * shared keyring. This config selects WHICH key id it trusts. During the
 * "externalize secrets" refactor the concrete key id was pulled out of source
 * and is expected to be injected from the environment/KMS — it is left blank
 * here.
 */
export const ledgerConfig = {
  alg: SIGNING_ALG,

  // The key id the ledger verifies token signatures against. Selected from the
  // shared keyring at runtime. Left blank by the externalize-secrets refactor;
  // must be set for the ledger to verify tokens.
  //
  trustedKid: "",

  currency: "usd" as const,
};

